<script>
  import { computeGeneralizedPgd, computeFgmOgm } from '@/lib/formula-lessons/part4-models.mjs';
  export let lesson; export let spec; let steps=spec.steps??6;
  $: generalized=spec.scene==='generalized-pgd'?computeGeneralizedPgd({...spec,steps:Number(steps)}):null; $: accel=spec.scene==='fgm-ogm'?computeFgmOgm({...spec,steps:Number(steps)}):null; const f=(v,d=4)=>Number(v).toFixed(d); const width=(v,m)=>Math.max(2,Math.min(100,100*v/Math.max(m,1e-12)));
</script>
<div class="lesson-grid" data-part4-acceleration data-focus={lesson.focus} data-scene={spec.scene}>{#if generalized}<section class="panel"><p class="eyebrow">S-Lipschitz PGD geometry</p><div class="metrics"><div><span>objective monotone</span><strong>{generalized.objectiveMonotone?'PASS':'FAIL'}</strong></div><div><span>weighted Fejér</span><strong>{generalized.fejerMonotone?'PASS':'FAIL'}</strong></div><div><span>matrix condition</span><strong>{generalized.matrixConditionSatisfied?'PASS':'FAIL'}</strong></div><div><span>steps</span><strong>{steps}</strong></div></div><label>iterations <output>{steps}</output><input bind:value={steps} type="range" min="2" max="8" step="1"/></label><div class="table-wrap"><table><thead><tr><th>k</th><th>f(xk)</th><th>||xk||P⁻¹</th></tr></thead><tbody>{#each generalized.history as row,i (row.k)}<tr><td>{row.k}</td><td>{f(row.objective)}</td><td>{f(generalized.distances[i])}</td></tr>{/each}</tbody></table></div></section><section class="panel"><p class="eyebrow">guarantee scale: O(1/k) vs O(1/k²)</p><div class="rate-bars">{#each generalized.classical as value,i (i)}<div><span>k={i+1}</span><i style={`width:${width(value,generalized.classical[0])}%`}></i><b>{f(value,2)}</b><i class="fast" style={`width:${width(generalized.accelerated[i],generalized.classical[0])}%`}></i><b>{f(generalized.accelerated[i],2)}</b></div>{/each}</div><p class="note">MAI-P4-214 keeps weighted Fejér monotonicity without claiming distance to every arbitrary minimizer converges to zero.</p></section>{:else if accel}<section class="panel"><p class="eyebrow">FGM recurrence</p><label>iterations <output>{steps}</output><input bind:value={steps} type="range" min="2" max="10" step="1"/></label><div class="table-wrap"><table><thead><tr><th>k</th><th>tₖ</th><th>β</th><th>f FGM</th><th>f OGM</th></tr></thead><tbody>{#each accel.fgm as row,i (row.k)}<tr><td>{row.k}</td><td>{f(row.t,3)}</td><td>{f(row.beta,3)}</td><td>{f(row.objective,4)}</td><td>{f(accel.ogm[i].objective,4)}</td></tr>{/each}</tbody></table></div></section><section class="panel"><p class="eyebrow">review invariants + constants</p><div class="metrics"><div><span>β⁽⁰⁾</span><strong>{f(accel.beta0,1)}</strong></div><div><span>β⁽⁰⁾=0</span><strong>{Math.abs(accel.beta0)<1e-12?'PASS':'FAIL'}</strong></div><div><span>tₙ≥(n+2)/2</span><strong>{accel.lowerBoundHolds?'PASS':'FAIL'}</strong></div><div><span>OGM bound factor</span><strong>½ FGM</strong></div></div><div class="rate-bars">{#each accel.fgmRate as value,i (i)}<div><span>k={i+1}</span><i style={`width:${width(value,accel.fgmRate[0])}%`}></i><b>{f(value,2)}</b><i class="fast" style={`width:${width(accel.ogmRate[i],accel.fgmRate[0])}%`}></i><b>{f(accel.ogmRate[i],2)}</b></div>{/each}</div><p class="note">215/216/217 corrections are checked against the same recurrence while 154/156/170 remain preserved source statements.</p></section>{/if}</div>
<style>.lesson-grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.panel{border:1px solid var(--color-border);border-radius:1rem;background:var(--color-background);padding:1rem}.eyebrow{margin:0 0 .5rem;font-size:.66rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--color-muted-foreground)}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.metrics div{display:grid;background:var(--color-muted);border-radius:.65rem;padding:.55rem;font-size:.72rem}.metrics span{color:var(--color-muted-foreground)}label{display:grid;grid-template-columns:1fr auto;margin-bottom:.5rem;font-size:.72rem;font-weight:800}input{grid-column:1/-1;min-height:30px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:.68rem}th,td{padding:.38rem;border-bottom:1px solid var(--color-border);text-align:right}.rate-bars{display:grid;gap:.35rem}.rate-bars div{display:grid;grid-template-columns:2.5rem 1fr 3.5rem 1fr 3.5rem;align-items:center;gap:.3rem;font-size:.64rem}.rate-bars i{display:block;height:.45rem;border-radius:999px;background:var(--color-muted-foreground)}.rate-bars i.fast{background:var(--color-primary)}.rate-bars b{text-align:right}.note{font-size:.73rem;line-height:1.65;color:var(--color-muted-foreground)}@media(max-width:760px){.lesson-grid{grid-template-columns:1fr}}</style>
